import json
import jsonschema
def main(generated_code):
    try:
        data = json.loads(generated_code)
        required_fields = ["name", "description", "nodes", "edges"]
        valid = all(f in data for f in required_fields)
        return {
            "valid": valid,
            "errors": [] if valid else ["缺少必要字段"],
            "json_size": len(generated_code),
            "status": "validated"
        }
    except Exception as e:
        return {
            "valid": False,
            "errors": [str(e)],
            "json_size": 0,
            "status": "validation_failed"
        }
